1	/**
2	 * Checks manifest-owned Aspire literals against the scaffold SDK pin.
3	 *
4	 * Phase 1 fails only scaffold constants, CI, and root config. Phase 2 is the
5	 * complete non-archival enforcement contract and is intentionally not enabled
6	 * in CI until the S13 slice.
7	 */
8	import { SCAFFOLD_VERSIONS } from '../../../packages/cli/src/kernel/constants/scaffold/scaffold-versions.ts';
9	import { buildAspireSurfaceManifest } from '../../runs/research-aspire-13.5-adoption--0.0.7/tools/aspire-surface-manifest.ts';
10	import { isTransientAspireScanPath } from './aspire-scan-scope.ts';
11	
12	export const ASPIRE_SURFACE_MANIFEST_PATH =
13	  '.llm/runs/research-aspire-13.5-adoption--0.0.7/aspire-surface-manifest.tsv';
14	
15	export type ParityPhase = 1 | 2;
16	export type FindingStatus = 'fail' | 'deferred' | 'info';
17	export const PHASE_TWO_COMPAT_VERSION = '13.5.3';
18	
19	export interface ManifestRow {
20	  path: string;
21	  class: string;
22	  owner: string;
23	  disposition: string;
24	}
25	
26	export interface ParityFinding {
27	  path: string;
28	  class: string;
29	  owner: string;
30	  status: FindingStatus;
31	  matches: string[];
32	  reason: string;
33	}
34	
35	export interface ParityReport {
36	  gate: 'check:aspire-version-parity';
37	  phase: ParityPhase;
38	  expectedVersion: string;
39	  manifest: string;
40	  ok: boolean;
41	  counts: {
42	    checked: number;
43	    fail: number;
44	    deferred: number;
45	    info: number;
46	    skipped: number;
47	    missing: number;
48	  };
49	  findings: ParityFinding[];
50	  skipped: string[];
51	  missing: string[];
52	  manifestFresh: boolean;
53	}
54	
55	interface EvaluateOptions {
56	  rows: readonly ManifestRow[];
57	  phase: ParityPhase;
58	  expectedVersion: string;
59	  readText: (path: string) => Promise<string | null>;
60	  manifestPath?: string;
61	  manifestSource?: string;
62	  generatedManifestSource?: string;
63	  generatedManifestUnmatched?: readonly string[];
64	}
65	
66	const STALE_PATTERNS = [/13\.[0-4]\.[0-9]+/g, /Aspire 13\.[0-4]/g] as const;
67	const VERSION_LITERAL_PATTERN =
68	  /(?<![0-9A-Za-z.])13\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?![0-9A-Za-z.-])/g;
69	
70	export const EXACT_ASPIRE_VERSION_TOKEN_MATCH = (
71	  candidate: string,
72	  expectedVersion: string,
73	): boolean => candidate.trim() === expectedVersion.trim();
74	
75	const PHASE_ONE_EXACT_VERSIONS: Readonly<Record<string, readonly string[]>> = {
76	  'packages/cli/src/kernel/constants/scaffold/scaffold-versions.ts': ['13.5.3', '13.5.0'],
77	  'packages/cli/src/kernel/constants/scaffold/scaffold-aspire.ts': [
78	    '13.5.3',
79	    '13.5.0',
80	    '13.5.3-preview.1.26425.3',
81	  ],
82	  '.github/toolchain.env': ['13.5.3'],
83	  '.github/scripts/aspire-nuget-cache-policy.test.ts': ['13.5.3', '13.5.3-v1'],
84	  '.github/workflows/e2e-cli.yml': ['13.5.3', '13.5.3-v1'],
85	  '.github/workflows/e2e-cli-prod.yml': ['13.5.3', '13.5.3-v1'],
86	  '.github/workflows/e2e-cli-prod-local.yml': ['13.5.3', '13.5.3-v1'],
87	};
88	
89	/** Remove only syntax explicitly permitted by the manifest-owned context. */
90	function pinSource(source: string, className: string): string {
91	  if (className === 'negative-version-guard') {
92	    // Deliberately not a TS parser: recognize only a standalone, direct three-argument
93	    // guard statement with an identifier input and literal/identifier location.
94	    // Unfamiliar syntax remains fail-closed.
95	    return source.replace(
96	      /^(\s*forbidText\(\s*[A-Za-z_$][\w$]*\s*,\s*)(['"])(13\.[0-4]\.[0-9]+)\2(?=\s*,\s*(?:[A-Za-z_$][\w$]*|'[^'\r\n]*'|"[^"\r\n]*")\s*,?\s*\)\s*;\s*$)/gm,
97	      '$1$2<forbidden version>$2',
98	    );
99	  }
100	  return source;
101	}
102	
103	function staleMatches(source: string, className: string): string[] {
104	  const pins = pinSource(source, className);
105	  return [
106	    ...new Set(STALE_PATTERNS.flatMap((pattern) => [...pins.matchAll(pattern)].map((m) => m[0]))),
107	  ];
108	}
109	
110	function unexpectedPhaseOneVersions(path: string, source: string): string[] {
111	  const allowed = PHASE_ONE_EXACT_VERSIONS[path];
112	  if (!allowed) return [];
113	  return [
114	    ...new Set(
115	      [...source.matchAll(VERSION_LITERAL_PATTERN)]
116	        .map((match) => match[0])
117	        .filter((version) => !allowed.includes(version)),
118	    ),
119	  ];
120	}
121	
122	function containsExactAspireVersionToken(source: string, expectedVersion: string): boolean {
123	  return [...source.matchAll(VERSION_LITERAL_PATTERN)]
124	    .map((match) => match[0])
125	    .some((candidate) => EXACT_ASPIRE_VERSION_TOKEN_MATCH(candidate, expectedVersion));
126	}
127	
128	function isPhaseOneFailClass(className: string): boolean {
129	  return className === 'scaffold-constants' || className === 'root-config' ||
130	    className.startsWith('ci:');
131	}
132	
133	function parityFinding(
134	  row: ManifestRow,
135	  status: FindingStatus,
136	  matches: string[],
137	  reason: string,
138	): ParityFinding {
139	  return {
140	    path: row.path,
141	    class: row.class,
142	    owner: row.owner,
143	    status,
144	    matches,
145	    reason,
146	  };
147	}
148	
149	export function parseManifest(source: string): ManifestRow[] {
150	  const lines = source.split(/\r?\n/).filter(Boolean);
151	  const header = lines.shift();
152	  if (header !== 'path\tclass\towner\tdisposition') {
153	    throw new Error(`Invalid Aspire surface manifest header: ${header ?? '<missing>'}`);
154	  }
155	  return lines.map((line, index) => {
156	    const [path, className, owner, disposition, ...extra] = line.split('\t');
157	    if (!path || !className || !owner || !disposition || extra.length > 0) {
158	      throw new Error(`Invalid Aspire surface manifest row ${index + 2}`);
159	    }
160	    return { path, class: className, owner, disposition };
161	  });
162	}
163	
164	/** Evaluates already-parsed manifest rows using an injected repository reader. */
165	export async function evaluateAspireVersionParity(
166	  options: EvaluateOptions,
167	): Promise<ParityReport> {
168	  const findings: ParityFinding[] = [];
169	  const skipped: string[] = [];
170	  const missing: string[] = [];
171	  let checked = 0;
172	  const sourcesMatch = options.manifestSource === undefined ||
173	    options.generatedManifestSource === undefined ||
174	    options.manifestSource === options.generatedManifestSource;
175	  const unmatched = options.generatedManifestUnmatched ?? [];
176	  const manifestFresh = sourcesMatch && unmatched.length === 0;
177	
178	  if (!manifestFresh) {
179	    findings.push(parityFinding(
180	      {
181	        path: options.manifestPath ?? ASPIRE_SURFACE_MANIFEST_PATH,
182	        class: 'manifest:freshness',
183	        owner: 'S13',
184	        disposition: 'regenerate before parity evaluation',
185	      },
186	      'fail',
187	      [...unmatched],
188	      unmatched.length > 0
189	        ? 'Aspire surface manifest has paths without an ownership rule'
190	        : 'Aspire surface manifest is stale; rerun aspire-surface-manifest.ts',
191	    ));
192	  }
193	
194	  for (const row of options.rows) {
195	    if (row.class === 'lockfile' || isTransientAspireScanPath(row.path)) {
196	      skipped.push(row.path);
197	      continue;
198	    }
199	    checked++;
200	    const source = await options.readText(row.path);
201	    if (source === null) {
202	      missing.push(row.path);
203	      if (row.owner !== 'archival') {
204	        findings.push(parityFinding(
205	          row,
206	          'fail',
207	          [],
208	          'required manifest path is missing',
209	        ));
210	      }
211	      continue;
212	    }
213	    const exactMismatches = options.phase === 1 ? unexpectedPhaseOneVersions(row.path, source) : [];
214	    const matches = [...new Set([...staleMatches(source, row.class), ...exactMismatches])];
215	
216	    if (row.owner === 'archival' || row.class.startsWith('archival:')) {
217	      if (matches.length > 0) {
218	        findings.push(
219	          parityFinding(row, 'info', matches, 'archival owner is informational only'),
220	        );
221	      }
222	      continue;
223	    }
224	
225	    if (options.phase === 2 && row.class === 'compat-fixture') {
226	      const hasExpectedVersion = containsExactAspireVersionToken(
227	        source,
228	        PHASE_TWO_COMPAT_VERSION,
229	      );
230	      findings.push(parityFinding(
231	        row,
232	        hasExpectedVersion ? 'info' : 'fail',
233	        matches,
234	        hasExpectedVersion
235	          ? `compat fixture contains the required ${PHASE_TWO_COMPAT_VERSION} literal`
236	          : `compat fixture is missing the required ${PHASE_TWO_COMPAT_VERSION} literal`,
237	      ));
238	      continue;
239	    }
240	
241	    if (matches.length === 0) continue;
242	    const fail = options.phase === 2 || isPhaseOneFailClass(row.class);
243	    findings.push(parityFinding(
244	      row,
245	      fail ? 'fail' : 'deferred',
246	      matches,
247	      exactMismatches.length > 0
248	        ? 'Aspire literal is outside the locked phase-1 pin policy'
249	        : fail
250	        ? `stale Aspire literal conflicts with ${options.expectedVersion}`
251	        : `stale Aspire literal is deferred to manifest owner ${row.owner}`,
252	    ));
253	  }
254	
255	  const count = (status: FindingStatus): number =>
256	    findings.filter((finding) => finding.status === status).length;
257	  const fail = count('fail');
258	  return {
259	    gate: 'check:aspire-version-parity',
260	    phase: options.phase,
261	    expectedVersion: options.expectedVersion,
262	    manifest: options.manifestPath ?? ASPIRE_SURFACE_MANIFEST_PATH,
263	    ok: fail === 0,
264	    counts: {
265	      checked,
266	      fail,
267	      deferred: count('deferred'),
268	      info: count('info'),
269	      skipped: skipped.length,
270	      missing: missing.length,
271	    },
272	    findings,
273	    skipped,
274	    missing,
275	    manifestFresh,
276	  };
277	}
278	
279	/** Parse the optional phase selector while preserving phase 1 as the default. */
280	export function parsePhase(args: string[]): ParityPhase {
281	  const index = args.indexOf('--phase');
282	  if (index === -1) return 1;
283	  const value = args[index + 1];
284	  if (value === '1' || value === '2') return Number(value) as ParityPhase;
285	  throw new Error(`--phase must be 1 or 2, received ${value ?? '<missing>'}`);
286	}
287	
288	async function readRepositoryFile(path: string): Promise<string | null> {
289	  try {
290	    return await Deno.readTextFile(path);
291	  } catch (error) {
292	    if (error instanceof Deno.errors.NotFound) return null;
293	    throw error;
294	  }
295	}
296	
297	export async function runParityGate(args: string[] = Deno.args): Promise<ParityReport> {
298	  const manifestSource = await Deno.readTextFile(ASPIRE_SURFACE_MANIFEST_PATH);
299	  const generatedManifest = await buildAspireSurfaceManifest();
300	  const phase = parsePhase(args);
301	  return await evaluateAspireVersionParity({
302	    rows: parseManifest(manifestSource),
303	    phase,
304	    expectedVersion: phase === 2 ? PHASE_TWO_COMPAT_VERSION : SCAFFOLD_VERSIONS.ASPIRE_SDK,
305	    readText: readRepositoryFile,
306	    manifestSource,
307	    generatedManifestSource: generatedManifest.body,
308	    generatedManifestUnmatched: generatedManifest.unmatched,
309	  });
310	}
311	
312	if (import.meta.main) {
313	  const report = await runParityGate();
314	  console.log(JSON.stringify(report));
315	  Deno.exit(report.ok || Deno.args.includes('--report') ? 0 : 1);
316	}
