1	import { relative, resolve } from '@std/path';
2	import { isTransientAspireScanPath } from './aspire-scan-scope.ts';
3	
4	/** A source file that appears to poll an Aspire describe snapshot on its own clock. */
5	export interface AspireResourcePollingFinding {
6	  readonly path: string;
7	  readonly describeLine: number;
8	}
9	
10	/**
11	 * Concurrency-fenced files temporarily exempt from the #1906 regrowth guard.
12	 *
13	 * This list may only shrink as their owning PRs land. It must not acquire an in-scope file merely
14	 * to make the guard green.
15	 */
16	export const ASPIRE_RESOURCE_POLL_ALLOWLIST: ReadonlySet<string> = new Set([]);
17	
18	const DESCRIBE_COMMAND = /['"`]describe['"`]/gu;
19	const FOLLOW_FLAG = /['"`]--follow['"`]/u;
20	const COMMAND_SIGNAL = /Deno\.Command|runAspire|AspireCommand/u;
21	const TIMING_SIGNAL = /Date\.now|setTimeout|\bdelay\s*\(|deadline|poll|timeout/iu;
22	const LOOP_START = /\b(?:while|for)\s*(?:await\s*)?\([^\n]*\)\s*\{/gu;
23	
24	/** Find source files that combine snapshot describe, iteration, and a local timing mechanism. */
25	export async function findAspireResourcePolling(
26	  sourceRoot: string,
27	  repositoryRoot: string = Deno.cwd(),
28	): Promise<readonly AspireResourcePollingFinding[]> {
29	  const findings: AspireResourcePollingFinding[] = [];
30	  for (const path of await typescriptFiles(sourceRoot, repositoryRoot)) {
31	    const source = await Deno.readTextFile(path);
32	    const loops = loopRanges(source);
33	    for (const match of source.matchAll(DESCRIBE_COMMAND)) {
34	      const index = match.index;
35	      const loop = loops.find((candidate) => candidate.start < index && index < candidate.end);
36	      if (!loop) continue;
37	      const body = source.slice(loop.start, loop.end);
38	      if (FOLLOW_FLAG.test(body) || !COMMAND_SIGNAL.test(body) || !TIMING_SIGNAL.test(body)) {
39	        continue;
40	      }
41	      findings.push({
42	        path: normalize(relative(repositoryRoot, path)),
43	        describeLine: source.slice(0, index).split(/\r?\n/u).length,
44	      });
45	      break;
46	    }
47	  }
48	  return findings.sort((left, right) => left.path.localeCompare(right.path));
49	}
50	
51	function loopRanges(source: string): readonly { start: number; end: number }[] {
52	  const ranges: { start: number; end: number }[] = [];
53	  for (const match of source.matchAll(LOOP_START)) {
54	    const open = source.indexOf('{', match.index);
55	    let depth = 0;
56	    for (let index = open; index < source.length; index += 1) {
57	      if (source[index] === '{') depth += 1;
58	      else if (source[index] === '}') depth -= 1;
59	      if (depth === 0) {
60	        ranges.push({ start: open, end: index + 1 });
61	        break;
62	      }
63	    }
64	  }
65	  return ranges;
66	}
67	
68	/** Render non-allowlisted findings as an actionable guard failure. */
69	export function unexpectedAspireResourcePolling(
70	  findings: readonly AspireResourcePollingFinding[],
71	): readonly AspireResourcePollingFinding[] {
72	  return findings.filter((finding) => !ASPIRE_RESOURCE_POLL_ALLOWLIST.has(finding.path));
73	}
74	
75	async function typescriptFiles(root: string, repositoryRoot: string): Promise<string[]> {
76	  const files: string[] = [];
77	  await visit(resolve(root), files, repositoryRoot);
78	  return files.sort((left, right) => left.localeCompare(right));
79	}
80	
81	async function visit(path: string, files: string[], repositoryRoot: string): Promise<void> {
82	  if (isTransientAspireScanPath(relative(repositoryRoot, path))) return;
83	  for await (const entry of Deno.readDir(path)) {
84	    const child = resolve(path, entry.name);
85	    if (entry.isDirectory) await visit(child, files, repositoryRoot);
86	    else if (
87	      entry.isFile && entry.name.endsWith('.ts') &&
88	      !isTransientAspireScanPath(relative(repositoryRoot, child))
89	    ) files.push(child);
90	  }
91	}
92	
93	function normalize(path: string): string {
94	  return path.replaceAll('\\', '/');
95	}
